<script setup>
import { computed, ref } from 'vue';
import { cast, photoThemes, stickers } from '../../data/playroom.js';
import { getTemplates, templatePayload, preserveTemplateDraft, previousTemplateDraft } from '../../room/templates.js';
const props=defineProps({tool:{type:String,required:true},current:{type:Object,required:true}}),emit=defineEmits(['apply']);
const expanded=ref(false),notice=ref(''),canRestore=ref(!!previousTemplateDraft(props.tool));
const templates=computed(()=>getTemplates(props.tool));
const payload=id=>templatePayload(id),asset=path=>`${import.meta.env.BASE_URL}${path}`;
const theme=id=>photoThemes.find(t=>t.id===payload(id).theme);
function apply(id){try{preserveTemplateDraft(props.tool,props.current);emit('apply',payload(id));canRestore.value=true;notice.value='模板已载入，可以继续编辑。替换前的草稿已保留，可点下方恢复。';}catch(error){notice.value=error.message;}}
function restore(){const value=previousTemplateDraft(props.tool);if(value){emit('apply',value);notice.value='已恢复使用模板前的草稿。';}else notice.value='没有找到可恢复的草稿。';}
</script>
<template><section class="template-library" aria-label="创作模板"><button type="button" class="template-toggle" :aria-expanded="expanded" @click="expanded=!expanded">{{expanded?'收起模板 −':'从一套模板开始 ＋'}}</button><div v-if="expanded" class="template-grid"><article v-for="item in templates" :key="item.id"><svg v-if="tool==='photobooth'" viewBox="0 0 720 900" role="img" :aria-label="`${item.title}真实模板预览`"><rect width="720" height="900" :fill="theme(item.id).paper"/><rect x="32" y="108" width="656" height="650" rx="120" :fill="theme(item.id).background"/><g v-for="o in payload(item.id).objects" :key="o.key" :transform="`translate(${o.x},${o.y}) rotate(${o.rotation})`"><image v-if="cast.some(c=>c.id===o.id)" :href="asset(cast.find(c=>c.id===o.id).image)" :x="-o.size/2" :y="-o.size/2" :width="o.size" :height="o.size"/><text v-else text-anchor="middle" dominant-baseline="middle" :fill="stickers.find(s=>s.id===o.id).color" :font-size="o.size*(o.id==='live'?.32:.8)" font-weight="800">{{stickers.find(s=>s.id===o.id).text}}</text></g><text x="360" y="813" text-anchor="middle" :fill="theme(item.id).ink" font-size="22">{{payload(item.id).caption}}</text></svg><svg v-else-if="tool==='comic'" :viewBox="payload(item.id).layout==='vertical'?'0 0 320 960':'0 0 640 480'" role="img" :aria-label="`${item.title}真实模板预览`"><rect width="640" height="480" fill="#f4e9d9"/><g v-for="(p,i) in payload(item.id).panels" :key="i" :transform="`translate(${payload(item.id).layout==='vertical'?8:10+i%2*315},${payload(item.id).layout==='vertical'?10+i*235:10+Math.floor(i/2)*235})`"><rect width="305" height="225" :fill="p.scene==='stage'?'#3d354d':p.scene==='street'?'#c6d9d2':'#e7cdd8'"/><g v-for="o in p.objects" :key="o.key"><image :href="asset(cast.find(c=>c.id===o.id).image)" :x="o.x/2-27" y="95" width="65" height="100"/></g><rect x="8" y="12" width="289" height="55" rx="8" fill="#fff8ed"/><text x="15" y="44" font-size="15" fill="#61445b">{{p.dialogue.slice(0,18)}}</text><text x="12" y="215" font-size="14" fill="#61445b">{{p.caption}}</text></g></svg><svg v-else-if="tool==='lights'" viewBox="0 0 900 520" role="img" :aria-label="`${item.title}真实模板第一步预览`"><rect width="900" height="520" fill="#292334"/><rect y="430" width="900" height="90" fill="#604e65"/><g v-for="(row,i) in payload(item.id).cues" :key="i"><path :d="`M${150+i*300} 35L${row[0].x-170} 445L${row[0].x+170} 445Z`" :fill="row[0].color" :opacity="row[0].intensity*.65"/></g><image v-for="(m,i) in cast" :key="m.id" :href="asset(m.image)" :x="150+i*170" y="275" width="110" height="165"/></svg><svg v-else viewBox="0 0 640 230" role="img" :aria-label="`${item.title}真实节拍预览`"><rect width="640" height="230" fill="#302738"/><g v-for="(mask,t) in payload(item.id).masks" :key="t"><rect v-for="step in 16" :key="step" :x="12+(step-1)*39" :y="12+t*52" width="32" height="42" rx="3" :fill="mask&(1<<(step-1))?['#dca3c1','#e9ca83','#a5c7db','#d98e9c'][t]:'#5c485f'"/></g></svg><h3>{{item.title}}</h3><p>{{item.description}}</p><button type="button" @click="apply(item.id)">使用这套模板 →</button></article></div><p v-if="notice" class="template-notice" role="status">{{notice}}</p><button v-if="canRestore" type="button" @click="restore">恢复使用模板前的草稿</button></section></template>
<style scoped>.template-library{margin:16px 0;border:1px dashed #a88a9d;padding:14px;background:#f9eee6;color:#5d4357}.template-library button{font:inherit;font-size:12px;min-height:44px;padding:8px 12px;cursor:pointer;border:1px solid #aa899d;background:#f3dfe7;color:#66495e}.template-toggle{width:100%;text-align:left}.template-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin-top:14px}.template-grid article{min-width:0;border:1px solid #d3bbc7;padding:12px;background:#fff8ee}.template-grid svg{width:100%;height:155px;object-fit:contain;background:#eadce2}.template-grid h3{font-size:16px;margin:12px 0 6px}.template-grid p,.template-notice{font-size:12px;line-height:1.8}.template-grid p{min-height:44px}.template-notice{color:#6d4d64}.template-grid button{width:100%}@media(max-width:500px){.template-grid{grid-template-columns:minmax(0,1fr)}.template-grid article{display:grid;grid-template-columns:100px minmax(0,1fr);gap:4px 12px;align-items:start}.template-grid svg{height:120px;grid-row:span 3}.template-grid h3{margin:0;font-size:15px}.template-grid p{margin:4px 0;min-height:0}.template-grid button{padding-inline:6px}}</style>
